"""A small PTY-backed interactive Bash terminal."""

from __future__ import annotations

import os
import pty
import select
import signal
import subprocess
import threading
import time
from typing import Optional

from base_terminal import BaseTerminal


class HeadlessTerminal(BaseTerminal):
    """Run an interactive Bash shell and send it terminal keystrokes.

    Output is consumed in the background so a full PTY buffer cannot block the
    shell. The most recent output is available as ``output`` and can also be
    retrieved with :meth:`read_output`.
    """

    def __init__(self, *, rows: int = 24, cols: int = 80,
                 cwd: Optional[str] = None, env: Optional[dict[str, str]] = None,
                 startup_timeout: float = 0.15) -> None:
        self._master_fd, slave_fd = pty.openpty()
        self._set_winsize(self._master_fd, rows, cols)
        shell_env = os.environ.copy()
        if env:
            shell_env.update(env)
        shell_env.setdefault("TERM", "xterm-256color")
        self._process = subprocess.Popen(
            ["bash", "--login", "-i"],
            stdin=slave_fd,
            stdout=slave_fd,
            stderr=slave_fd,
            cwd=cwd,
            env=shell_env,
            start_new_session=True,
            close_fds=True,
        )
        os.close(slave_fd)
        os.set_blocking(self._master_fd, False)
        self._output = bytearray()
        self._output_lock = threading.Lock()
        self._closed = False
        self._reader = threading.Thread(target=self._read_loop, name="terminal-reader", daemon=True)
        self._reader.start()
        if startup_timeout > 0:
            time.sleep(startup_timeout)

    @staticmethod
    def _set_winsize(fd: int, rows: int, cols: int) -> None:
        import fcntl
        import struct
        import termios
        fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))

    def _read_loop(self) -> None:
        while not self._closed:
            try:
                ready, _, _ = select.select([self._master_fd], [], [], 0.1)
                if not ready:
                    if self._process.poll() is not None:
                        return
                    continue
                chunk = os.read(self._master_fd, 65536)
                if not chunk:
                    return
                with self._output_lock:
                    self._output.extend(chunk)
            except (OSError, ValueError):
                return

    @property
    def output(self) -> str:
        """Return all terminal output received so far, decoded with replacement."""
        with self._output_lock:
            return self._output.decode("utf-8", errors="replace")

    def read_output(self, *, clear: bool = False) -> str:
        """Read accumulated terminal output, optionally clearing the buffer."""
        with self._output_lock:
            result = self._output.decode("utf-8", errors="replace")
            if clear:
                self._output.clear()
            return result

    def send_keystrokes(self, keystrokes: str, wait_sec: float = 0.0) -> None:
        """Write key bytes to the PTY and optionally allow the shell to respond."""
        if self._closed or self._process.poll() is not None:
            raise RuntimeError("terminal shell is not running")
        data = keystrokes.encode("utf-8")
        view = memoryview(data)
        while view:
            try:
                n = os.write(self._master_fd, view)
                view = view[n:]
            except BlockingIOError:
                select.select([], [self._master_fd], [], 0.1)
            except OSError as exc:
                raise RuntimeError("could not write to terminal") from exc
        if wait_sec > 0:
            time.sleep(wait_sec)

    def resize(self, rows: int, cols: int) -> None:
        """Change the PTY dimensions and notify the foreground process."""
        if rows <= 0 or cols <= 0:
            raise ValueError("rows and cols must be positive")
        self._set_winsize(self._master_fd, rows, cols)
        try:
            os.killpg(self._process.pid, signal.SIGWINCH)
        except ProcessLookupError:
            pass

    def close(self) -> None:
        """Close the terminal and terminate its shell process group."""
        if self._closed:
            return
        self._closed = True
        if self._process.poll() is None:
            try:
                os.killpg(self._process.pid, signal.SIGHUP)
            except ProcessLookupError:
                pass
            try:
                self._process.wait(timeout=1)
            except subprocess.TimeoutExpired:
                try:
                    os.killpg(self._process.pid, signal.SIGKILL)
                except ProcessLookupError:
                    pass
                self._process.wait()
        try:
            os.close(self._master_fd)
        except OSError:
            pass
        self._reader.join(timeout=0.2)

    def __enter__(self) -> "HeadlessTerminal":
        return self

    def __exit__(self, exc_type, exc, tb) -> None:
        self.close()

    def __del__(self) -> None:
        try:
            self.close()
        except Exception:
            pass

